// --- Signed request helper (identical scheme to Convex convex/lib/crypto.ts) ---
// signature = "sha256=" + hex(HMAC_SHA256(LENDLOOP_AUTOMATION_SECRET, `${timestamp}.${nonce}.${body}`))
// `body` is the exact string the next HTTP Request node sends as its raw body.
const crypto = require('crypto');
function signedRequest(path, payload) {
  const secret = $env.LENDLOOP_AUTOMATION_SECRET;
  const base = String($env.LENDLOOP_CONVEX_SITE_URL || '').trim().replace(/\/+$/, '');
  if (typeof secret !== 'string' || secret.length < 32) throw new Error('LENDLOOP_AUTOMATION_SECRET is not configured');
  if (!/^https?:\/\/\S+$/.test(base)) throw new Error('LENDLOOP_CONVEX_SITE_URL is not configured');
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const nonce = crypto.randomUUID();
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${nonce}.${body}`).digest('hex');
  return { url: base + path, body, timestamp, nonce, signature };
}
// -----------------------------------------------------------------------------
// Ask Convex which loans are overdue and still need today's reminder.
// Convex picks the period (UTC date) itself; optional body fields: period "YYYY-MM-DD", limit 1-200.
const startedAt = Date.now();
const request = signedRequest('/automation/overdue/candidates', { executionId: String($execution.id) });
return [{ json: { startedAt, request } }];

// One item per candidate loan. With no candidates, a single marker item goes straight
// to "Summarize Run" so an empty run is still reported to Convex.
const res = $input.first().json;
const period = res.period;
if (typeof period !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(period)) {
  throw new Error('Unexpected /automation/overdue/candidates response: missing period');
}
if (!Array.isArray(res.items)) throw new Error('Unexpected /automation/overdue/candidates response: missing items');

const seen = new Set();
const items = [];
for (const c of res.items) {
  if (!c || typeof c.loanId !== 'string' || !/^[A-Za-z0-9]{1,64}$/.test(c.loanId) || seen.has(c.loanId)) continue;
  seen.add(c.loanId);
  items.push({ json: { loanId: c.loanId, period, daysOverdue: Number.isInteger(c.daysOverdue) ? c.daysOverdue : null } });
}
return items.length > 0 ? items : [{ json: { noCandidates: true, period } }];

// --- Signed request helper (identical scheme to Convex convex/lib/crypto.ts) ---
// signature = "sha256=" + hex(HMAC_SHA256(LENDLOOP_AUTOMATION_SECRET, `${timestamp}.${nonce}.${body}`))
// `body` is the exact string the next HTTP Request node sends as its raw body.
const crypto = require('crypto');
function signedRequest(path, payload) {
  const secret = $env.LENDLOOP_AUTOMATION_SECRET;
  const base = String($env.LENDLOOP_CONVEX_SITE_URL || '').trim().replace(/\/+$/, '');
  if (typeof secret !== 'string' || secret.length < 32) throw new Error('LENDLOOP_AUTOMATION_SECRET is not configured');
  if (!/^https?:\/\/\S+$/.test(base)) throw new Error('LENDLOOP_CONVEX_SITE_URL is not configured');
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const nonce = crypto.randomUUID();
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${nonce}.${body}`).digest('hex');
  return { url: base + path, body, timestamp, nonce, signature };
}
// -----------------------------------------------------------------------------
// Idempotency: Convex only answers "claimed" once per loan per period.
const { loanId, period } = $input.first().json;
const request = signedRequest('/automation/reminders/claim', { loanId, period, executionId: String($execution.id) });
return [{ json: { loanId, period, request } }];

// Convex did not hand out this reminder (duplicate / in_progress / not_overdue / skipped / unknown).
const { loanId } = $('Loop Over Candidates').first().json;
const status = String($input.first().json.status ?? 'unknown').slice(0, 30);
return [{ json: { loanId, outcome: 'SKIPPED', status } }];

// Build the reminder from the text Convex returned with the claim (no other data).
const r = $input.first().json;
const mode = String($env.LENDLOOP_EMAIL_MODE || 'mock').trim().toLowerCase() === 'smtp' ? 'smtp' : 'mock';
const subject = String(r.message?.subject ?? 'LendLoop reminder').replace(/[\r\n]+/g, ' ').slice(0, 200);
const text = `${String(r.message?.body ?? '')}\n\n${String(r.link ?? '')}`.trim();
return [{ json: { mode, email: { to: String(r.recipient?.email ?? ''), subject, text } } }];

// --- Redaction helper: never forward emails, signatures, secrets or OTP-like numbers ---
function redact(text, max = 1000) {
  let s = String(text ?? '');
  for (const name of ['LENDLOOP_AUTOMATION_SECRET', 'LENDLOOP_N8N_WEBHOOK_SECRET']) {
    const v = $env[name];
    if (typeof v === 'string' && v.length >= 16) s = s.split(v).join('[redacted]');
  }
  return s
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[email]')
    .replace(/\b(bearer|basic)\s+[A-Za-z0-9._~+/=-]+/gi, '$1 [redacted]')
    .replace(/sha256=[A-Fa-f0-9]+/g, 'sha256=[redacted]')
    .replace(/\b(password|passwd|pass|secret|token|api[_-]?key|authorization)(["']?\s*[:=]\s*["']?)[^\s"',;&}]+/gi, '$1$2[redacted]')
    .replace(/\b\d{6,}\b/g, '[number]')
    .slice(0, max);
}
// -----------------------------------------------------------------------------
// "Send Email" runs with On Error = continue. Only report SENT on positive evidence from the
// SMTP server: if the node failed before sending (e.g. missing credential) n8n passes the
// input item through unchanged, without an `error` field.
const out = $input.first().json;
const fail = (why) => [{ json: { result: 'FAILED', error: redact(`SMTP send failed: ${why}`) } }];
if (out.error) {
  const e = out.error;
  return fail(typeof e === 'string' ? e : (e.message || e.description || 'unknown error'));
}
if (Array.isArray(out.rejected) && out.rejected.length > 0) return fail('recipient rejected by the SMTP server');
const accepted = Array.isArray(out.accepted) && out.accepted.length > 0;
if (!accepted && typeof out.messageId !== 'string') {
  return fail('the Send Email node returned no SMTP result - check that the "LendLoop SMTP" credential exists and is selected');
}
return [{ json: { result: 'SENT' } }];

// --- Signed request helper (identical scheme to Convex convex/lib/crypto.ts) ---
// signature = "sha256=" + hex(HMAC_SHA256(LENDLOOP_AUTOMATION_SECRET, `${timestamp}.${nonce}.${body}`))
// `body` is the exact string the next HTTP Request node sends as its raw body.
const crypto = require('crypto');
function signedRequest(path, payload) {
  const secret = $env.LENDLOOP_AUTOMATION_SECRET;
  const base = String($env.LENDLOOP_CONVEX_SITE_URL || '').trim().replace(/\/+$/, '');
  if (typeof secret !== 'string' || secret.length < 32) throw new Error('LENDLOOP_AUTOMATION_SECRET is not configured');
  if (!/^https?:\/\/\S+$/.test(base)) throw new Error('LENDLOOP_CONVEX_SITE_URL is not configured');
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const nonce = crypto.randomUUID();
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${nonce}.${body}`).digest('hex');
  return { url: base + path, body, timestamp, nonce, signature };
