// -----------------------------------------------------------------------------
// Record the reminder outcome for this loan/period.
const { loanId, period } = $('Loop Over Candidates').first().json;
const { result, error } = $input.first().json;
const payload = { loanId, period, result };
if (result === 'FAILED') payload.error = String(error || 'Email delivery failed').slice(0, 1000);
return [{ json: { loanId, result, request: signedRequest('/automation/reminders/report', payload) } }];

// Reminder handled and reported: SENT, MOCKED or FAILED (SMTP error).
const { loanId, result } = $('Sign Reminder Report').first().json;
return [{ json: { loanId, outcome: result } }];

// --- Redaction helper: never forward emails, signatures, secrets or OTP-like numbers ---
function redact(text, max = 1000) {
  let s = String(text ?? '');
  for (const name of ['LENDLOOP_AUTOMATION_SECRET', 'LENDLOOP_N8N_WEBHOOK_SECRET']) {
    const v = $env[name];
    if (typeof v === 'string' && v.length >= 16) s = s.split(v).join('[redacted]');
  }
  return s
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[email]')
    .replace(/\b(bearer|basic)\s+[A-Za-z0-9._~+/=-]+/gi, '$1 [redacted]')
    .replace(/sha256=[A-Fa-f0-9]+/g, 'sha256=[redacted]')
    .replace(/\b(password|passwd|pass|secret|token|api[_-]?key|authorization)(["']?\s*[:=]\s*["']?)[^\s"',;&}]+/gi, '$1$2[redacted]')
    .replace(/\b\d{6,}\b/g, '[number]')
    .slice(0, max);
}
// -----------------------------------------------------------------------------
// A Convex call for this loan failed after retries. Count it and continue with the next loan.
const { loanId } = $('Loop Over Candidates').first().json;
const e = $input.first().json.error;
const message = typeof e === 'string' ? e : (e?.message || 'request failed');
return [{ json: { loanId, outcome: 'FAILED', stage: $prevNode.name, error: redact(message, 300) } }];

// --- Signed request helper (identical scheme to Convex convex/lib/crypto.ts) ---
// signature = "sha256=" + hex(HMAC_SHA256(LENDLOOP_AUTOMATION_SECRET, `${timestamp}.${nonce}.${body}`))
// `body` is the exact string the next HTTP Request node sends as its raw body.
const crypto = require('crypto');
function signedRequest(path, payload) {
  const secret = $env.LENDLOOP_AUTOMATION_SECRET;
  const base = String($env.LENDLOOP_CONVEX_SITE_URL || '').trim().replace(/\/+$/, '');
  if (typeof secret !== 'string' || secret.length < 32) throw new Error('LENDLOOP_AUTOMATION_SECRET is not configured');
  if (!/^https?:\/\/\S+$/.test(base)) throw new Error('LENDLOOP_CONVEX_SITE_URL is not configured');
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const nonce = crypto.randomUUID();
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${nonce}.${body}`).digest('hex');
  return { url: base + path, body, timestamp, nonce, signature };
}
// -----------------------------------------------------------------------------
// Aggregate per-loan outcomes (or the "no candidates" marker) and report the run.
const outcomes = $input.all().map((i) => i.json).filter((j) => typeof j.outcome === 'string');
const count = (...values) => outcomes.filter((o) => values.includes(o.outcome)).length;
const summary = {
  workflowName: 'lendloop-overdue-reminders',
  executionId: String($execution.id),
  processed: outcomes.length,
  sent: count('SENT', 'MOCKED'),
  skipped: count('SKIPPED'),
  failed: count('FAILED'),
  startedAt: $('Request Candidates').first().json.startedAt,
};
return [{ json: { summary, request: signedRequest('/automation/runs', summary) } }];

// Final output (shown by `n8n execute`): the counts that were recorded in Convex.
const { summary } = $('Summarize Run').first().json;
return [{ json: { recorded: $input.first().json.ok === true, ...summary } }];
